Q: Bitwise operation not working as expected (C using Gameboy development kit) A: <pre><code>#include &lt;stdio.h&gt;

#define UINT8 unsigned char


UINT8 setNibble(UINT8 orig, UINT8 value) {
    UINT8 rtn = 0;
    rtn = (orig &amp; 0b11110000) | (value &amp; 0b00001111); //doesn't work, returns 0
    //rtn = (64 &amp; 240) | (2 &amp; 15);                      //works, basic values, returns a 66
    //rtn = (64 &amp; 240) | (value &amp; 15);                  //works, without orig, returns a 66
    //rtn = (orig &amp; 240) | (value &amp; 15);                //doesn't work, returns 64               
    //UINT8 mask  = (UINT8)0xF0;          //solution suggested by Stackoverflow AI
    //UINT8 low   = (UINT8)(value &amp; 0x0F);
    //rtn = (UINT8)((orig &amp; mask) | low);                 //doesn't work, returns a 2
    return rtn;
}
int main() {
    UINT8 num = setNibble(65,2); 

    printf(&quot;ORIG %02x\n&quot;, 65);
    printf(&quot;VALU %02x\n&quot;, 2);
    printf(&quot;RES  %02x\n&quot;, num);

    return 0;
}
</code></pre>
<p>generates what is expected</p>
<pre><code>ORIG 41
VALU 02
RES  42
</code></pre>

Q: How to solve a Box Claw mover so it spread all boxes evenly on all available stacks? A: <p>Complex much?</p>
<pre><code>function solve(clawPos, boxes, boxInClaw) {
    const pileIndex = findPile(boxes, boxInClaw);
    return operateClaw(clawPos, pileIndex, boxInClaw)
}

const findPile = (boxes, boxInClaw) =&gt; {
    return boxInClaw ? boxes.findIndex(item =&gt; item === Math.min(...boxes)) : boxes.findLastIndex(item =&gt; item === Math.max(...boxes));
}

const operateClaw = (clawPos, targetPile, boxInClaw) =&gt; {
    if (clawPos &lt; targetPile) {
        return &quot;RIGHT&quot;;
    } else if (clawPos &gt; targetPile) {
        return &quot;LEFT&quot;;
    } else {
        return boxInClaw ? &quot;PLACE&quot; : &quot;PICK&quot;;
    }
}
</code></pre>
